namespace PZ3D {
 internal sealed class PlayProfileRecovery {
  public bool pending,canRecover;public string state="none",stamp="";public string[] locations=new string[0],warnings=new string[0];
 }
 internal sealed class PlayProfileResult {
  public string status,message,profileId;public bool recoveryPending;public PlayProfileRecovery pendingRecovery;
 }
 // A profile-specific transaction, deliberately excluding launch/Steam/update operations.
 internal static class PlayProfileTransaction {
  internal const string PendingMessage="游玩配置应用尚未恢复；请先查看配置恢复状态并明确确认恢复。";
  internal sealed class Slot {public string target;internal byte[] before,after;}
  sealed class Entry {public string target,before,after;public bool attempted;}
  sealed class Record {public int version=1;public string id,binding,profileId,targetKind,targetId,stage;public List<Entry> entries=new List<Entry>();internal byte[] Raw;}
  sealed class Lease:IDisposable {readonly Mutex mutex;internal Lease(string name){mutex=new Mutex(false,name);bool held=false;try{try{held=mutex.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("其他启动或配置任务仍在处理，请稍后重试。");}catch{mutex.Dispose();throw;}}public void Dispose(){mutex.ReleaseMutex();mutex.Dispose();}}
  internal static IDisposable Lock(Engine e,string store=null){return new Lease(store==null?"Local\\OrangeLaunch-"+Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(e.User).ToUpperInvariant())):"Local\\OrangePlayProfiles-"+Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(store).ToUpperInvariant())));}
  internal static string Hash(byte[] bytes){return bytes==null?"absent":DlssInstaller.Hash(bytes);}
  internal static bool Same(byte[] a,byte[] b){return a==null?b==null:b!=null&&a.SequenceEqual(b);}
  internal static byte[] Read(string path,int maximum=2097152){LauncherMaintenance.NoReparse(path);if(!File.Exists(path)){if(Directory.Exists(path))throw new IOException("文件目标为目录。");return null;}using(var s=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(s.Length>maximum)throw new IOException("配置文件超出读取限制。");var bytes=new byte[(int)s.Length];int at=0,count;while(at<bytes.Length&&(count=s.Read(bytes,at,bytes.Length-at))>0)at+=count;if(at!=bytes.Length)throw new IOException("文件读取未完成。");return bytes;}}
  static string Binding(Engine e){return Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(e.Game).ToUpperInvariant()+"|"+Path.GetFullPath(e.User).ToUpperInvariant()+"|"+Path.GetFullPath(e.Data).ToUpperInvariant()));}
  static string Namespace(Engine e){string path=Path.Combine(e.Data,"play-profile-transactions");LauncherMaintenance.NoReparse(path);return path;}
  static string Root(Engine e){string path=Path.Combine(Namespace(e),LaunchProfiles.Key(e));LauncherMaintenance.NoReparse(path);return path;}
  internal static string Journal(Engine e){return Path.Combine(Root(e),"pending.json");}
  internal static bool HasOwnJournal(Engine e){try{string file=Journal(e);LauncherMaintenance.NoReparse(file);return File.Exists(file)||Directory.Exists(file);}catch{return false;}}
  // Global properties are shared by installations using this Data directory. Inspect only
  // the bounded native journal namespace; detecting pending never parses a foreign body.
  internal static bool Pending(Engine e){try{string root=Namespace(e);if(File.Exists(root))return true;if(!Directory.Exists(root))return false;string[] entries=Directory.EnumerateFileSystemEntries(root).Take(129).ToArray();if(entries.Length>128)return true;foreach(string entry in entries){LauncherMaintenance.NoReparse(entry);if(!Directory.Exists(entry)||!Regex.IsMatch(Path.GetFileName(entry),"^[A-F0-9]{64}$"))return true;string journal=Path.Combine(entry,"pending.json");LauncherMaintenance.NoReparse(journal);if(File.Exists(journal)||Directory.Exists(journal))return true;}return false;}catch{return true;}}
  static string Transaction(Engine e,Record r){if(!PlayProfiles.Id(r.id))throw new IOException("事务标识无效。");string path=Path.Combine(Root(e),r.id);LauncherMaintenance.NoReparse(path);return path;}
  static string Backup(Engine e,Record r,int index,bool after){return Path.Combine(Transaction(e,r),index+(after?".after":".before"));}
  static string Target(Engine e,Record r,string slot){if(slot=="config")return e.Config;if(ViewpointSettings.Files.Contains(slot))return Path.Combine(e.User,slot);if(slot=="defaultMods"&&r.targetKind=="normal")return e.Mods;if(slot=="saveMods"&&r.targetKind=="save"){string path=SaveProfiles.ResolveSave(e,r.targetId);if(r.targetId.Split('/')[0].Equals("Multiplayer",StringComparison.OrdinalIgnoreCase))throw new IOException("联机存档只读。");return Path.Combine(path,"mods.txt");}throw new IOException("恢复记录目标不在允许范围。");}
  static string Label(string slot){return slot=="config"?"启动 JSON":slot=="defaultMods"?"默认模组清单":slot=="saveMods"?"所选存档模组清单":"Viewpoint 实际设置";}
  static string Stage(string target,Record r,int index){return Path.Combine(Path.GetDirectoryName(target),".orange-profile-"+r.id+"-"+index);}
  static DirectorySecurity DirectoryAcl(){var s=new DirectorySecurity();var user=WindowsIdentity.GetCurrent().User;s.SetAccessRuleProtection(true,false);s.SetOwner(user);s.AddAccessRule(new FileSystemAccessRule(user,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));return s;}
  static FileSecurity FileAcl(){var s=new FileSecurity();var user=WindowsIdentity.GetCurrent().User;s.SetAccessRuleProtection(true,false);s.SetOwner(user);s.AddAccessRule(new FileSystemAccessRule(user,FileSystemRights.FullControl,AccessControlType.Allow));return s;}
  static void Private(string path){LauncherMaintenance.NoReparse(path);if(!Directory.Exists(path))Directory.CreateDirectory(path,DirectoryAcl());}
  static void WriteNew(string path,byte[] bytes){LauncherMaintenance.NoReparse(path);using(var s=new FileStream(path,FileMode.CreateNew,FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,FileAcl())){s.Write(bytes,0,bytes.Length);s.Flush(true);}}
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct RenameInformation {internal uint ReplaceIfExists;internal IntPtr RootDirectory;internal uint FileNameLength;internal char FileName;}
  [DllImport("kernel32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]static extern bool SetFileInformationByHandle(Microsoft.Win32.SafeHandles.SafeFileHandle file,int informationClass,IntPtr information,uint size);
  // Same ownership boundary as the accepted Buddy compensation: hold exact bytes exclusively,
  // rename that handle without replacement, then fill the absent name without overwriting a writer.
  static bool RetireOwned(string target,string retired,byte[] expected,Action afterRetire){foreach(string path in new[]{target,retired})LauncherMaintenance.NoReparse(path);using(var owned=new FileStream(target,FileMode.Open,FileSystemRights.Read|FileSystemRights.Delete,FileShare.None,4096,FileOptions.None)){if(owned.Length!=expected.Length)return false;var block=new byte[4096];int at=0,count;while((count=owned.Read(block,0,block.Length))>0){for(int i=0;i<count;i++)if(block[i]!=expected[at+i])return false;at+=count;}if(at!=expected.Length)return false;byte[] name=Encoding.Unicode.GetBytes(Path.GetFullPath(retired));int offset=Marshal.OffsetOf(typeof(RenameInformation),"FileName").ToInt32(),length=checked(offset+name.Length+2);IntPtr info=Marshal.AllocHGlobal(length);try{Marshal.Copy(new byte[length],0,info,length);Marshal.WriteInt32(info,Marshal.OffsetOf(typeof(RenameInformation),"FileNameLength").ToInt32(),name.Length);Marshal.Copy(name,0,IntPtr.Add(info,offset),name.Length);if(!SetFileInformationByHandle(owned.SafeFileHandle,3,info,(uint)length))throw new Win32Exception(Marshal.GetLastWin32Error());}finally{Marshal.FreeHGlobal(info);}if(afterRetire!=null)afterRetire();}return true;}
  static void MoveAbsent(string source,string target){LauncherMaintenance.NoReparse(source);LauncherMaintenance.NoReparse(target);File.Move(source,target);}
  internal static void WriteOwnedData(string file,byte[] before,byte[] after,Action guard){LauncherMaintenance.NoReparse(file);string parent=Path.GetDirectoryName(file);LauncherMaintenance.NoReparse(parent);Directory.CreateDirectory(parent);string dir=Path.Combine(parent,".orange-data-"+Guid.NewGuid().ToString("N"));Private(dir);string candidate=Path.Combine(dir,"new"),old=Path.Combine(dir,"old");WriteNew(candidate,after);guard();if(!Same(before,Read(file)))throw new IOException("数据已被其他程序修改。");if(before==null)MoveAbsent(candidate,file);else{File.Replace(candidate,file,old);if(!Same(before,Read(old))){RetireOwned(file,Path.Combine(dir,"retired"),after,()=>MoveAbsent(old,file));throw new IOException("并发修改已保留，拒绝覆盖配置数据。");}}}
  static void Save(Engine e,Record r,string stage){r.stage=stage;byte[] next=Encoding.UTF8.GetBytes(PlayProfileJson.Serializer().Serialize(r));if(next.Length>32768)throw new IOException("事务记录超出限制。");string journal=Journal(e);if(r.Raw==null)WriteNew(journal,next);else WriteOwnedData(journal,r.Raw,next,()=>{if(!Same(r.Raw,Read(journal,32768)))throw new IOException("事务记录已被修改。");});r.Raw=next;}
  static Record Load(Engine e){byte[] bytes=Read(Journal(e),32768);if(bytes==null)throw new IOException("事务记录不存在。");var raw=PlayProfileJson.Object(PlayProfileJson.Utf8.GetString(bytes),32768);PlayProfileJson.Keys(raw,"version","id","binding","profileId","targetKind","targetId","stage","entries");if(!(raw["version"] is int)||new[]{"id","binding","profileId","targetKind","targetId","stage"}.Any(k=>!(raw[k] is string)))throw new IOException("事务字段类型无效。");var r=PlayProfileJson.Serializer().Deserialize<Record>(PlayProfileJson.Utf8.GetString(bytes));if(r==null||r.version!=1||!PlayProfiles.Id(r.id)||!PlayProfiles.Id(r.profileId)||r.binding!=Binding(e)||!new[]{"normal","save","server"}.Contains(r.targetKind)||r.targetId==null||r.targetId.Length>260||r.targetKind=="normal"&&r.targetId!=""||r.targetKind=="server"&&!PlayProfiles.Id(r.targetId)||!new[]{"prepared","applying","rollingBack","recoveryRequired","completed","failed","recovered"}.Contains(r.stage)||r.entries==null||r.entries.Count<1||r.entries.Count>5)throw new IOException("事务记录身份或格式无效。");if(!(raw["entries"] is object[]))throw new IOException("事务条目无效。");foreach(var item in (object[])raw["entries"]){var entry=item as Dictionary<string,object>;PlayProfileJson.Keys(entry,"target","before","after","attempted");if(!(entry["attempted"] is bool)||new[]{"target","before","after"}.Any(k=>!(entry[k] is string)))throw new IOException("事务状态类型无效。");}var slots=new HashSet<string>();long total=0;for(int i=0;i<r.entries.Count;i++){var v=r.entries[i];if(v==null||!slots.Add(v.target)||v.before!="absent"&&!Regex.IsMatch(v.before??"","^[A-F0-9]{64}$")||!Regex.IsMatch(v.after??"","^[A-F0-9]{64}$"))throw new IOException("事务校验字段无效。");string path=Target(e,r,v.target);LauncherMaintenance.NoReparse(path);byte[] before=Read(Backup(e,r,i,false),v.target=="config"?2097152:1048576),after=Read(Backup(e,r,i,true),v.target=="config"?2097152:1048576);if(Hash(before)!=v.before||Hash(after)!=v.after)throw new IOException("事务备份校验失败。");total+=(before==null?0:before.Length)+after.Length;StageEvidence(path,r,i,v);}if(total>12582912)throw new IOException("事务备份累计大小超限。");r.Raw=bytes;return r;}
  static string StageEvidence(string target,Record r,int index,Entry entry){string folder=Stage(target,r,index);LauncherMaintenance.NoReparse(folder);if(!Directory.Exists(folder))return "absent";var parts=new List<string>();string[] files=Directory.EnumerateFileSystemEntries(folder).Take(6).ToArray();if(files.Length>5)throw new IOException("事务暂存证据包含未知文件。");foreach(string file in files){string name=Path.GetFileName(file);if(!new[]{"new","old","retired","restore","foreign"}.Contains(name))throw new IOException("事务暂存证据越界。");string hash=Hash(Read(file,entry.target=="config"?2097152:1048576));if(name=="foreign"||hash!=entry.before&&hash!=entry.after)throw new IOException("事务含外部修改证据，需人工核对。");parts.Add(name+":"+hash);}return string.Join("|",parts.OrderBy(x=>x));}
  static void Safe(Engine e,Func<bool> running){foreach(string path in new[]{e.Game,e.Config,e.User,e.Mods,e.Data,Journal(e)})LauncherMaintenance.NoReparse(path);if(BuddyTakeover.Pending(e)||File.Exists(Path.Combine(e.Data,"workshop-rebuild.pending")))throw new IOException("其他启动、参数或工坊任务尚未恢复。");}
  internal static PlayProfileRecovery Recovery(Engine e,Func<bool> running){var state=new PlayProfileRecovery{pending=Pending(e)};if(!state.pending)return state;state.state="manual";state.warnings=new[]{"事务文件或外部改动需要核对；未自动恢复，证据已保留。"};if(!HasOwnJournal(e)){state.warnings=new[]{"其他目录或未知事务状态仍需核对；如更改过游戏目录，请通过本机选择窗口返回原目录后明确恢复。"};return state;}try{Safe(e,running);var r=Load(e);state.locations=r.entries.Select(x=>Label(x.target)).Distinct().ToArray();var fingerprints=new List<string>{Binding(e),Hash(r.Raw)};for(int i=0;i<r.entries.Count;i++){var entry=r.entries[i];string path=Target(e,r,entry.target),current=Hash(Read(path,entry.target=="config"?2097152:1048576));if(current!=entry.before&&current!=entry.after)return state;fingerprints.Add(current+"|"+entry.before+"|"+entry.after+"|"+StageEvidence(path,r,i,entry));}state.stamp="playRecovery:"+Hash(Encoding.UTF8.GetBytes(string.Join("\n",fingerprints)));state.canRecover=true;state.state="recoverable";state.warnings=new[]{"确认后只恢复仍匹配本轮写入的配置；不会覆盖外部修改。"};}catch{}return state;}
  static void Finish(Engine e,Record r,string stage){Save(e,r,stage);string result=Path.Combine(Transaction(e,r),"result.json");if(!RetireOwned(Journal(e),result,r.Raw,null))throw new IOException("事务记录已改变，未移除恢复记录。");}
  static void Hook(Action<string,int> hook,string phase,int index){if(hook!=null)hook(phase,index);}
  static void Forward(Engine e,Record r,int index,Slot slot,Action<string,int> hook,Func<LauncherMemoryInfo> memory,int? heap,Func<bool> cancelled,Func<bool> running){string target=Target(e,r,slot.target);if(!Same(slot.before,Read(target,slot.target=="config"?2097152:1048576)))throw new IOException("预览后目标发生外部修改。");string folder=Stage(target,r,index);Private(folder);string candidate=Path.Combine(folder,"new"),old=Path.Combine(folder,"old");WriteNew(candidate,slot.after);Hook(hook,"beforeReplace",index);Safe(e,running);if(cancelled())throw new OperationCanceledException();if(heap.HasValue)LauncherMaintenance.CheckProfileHeap(heap.Value,memory);if(slot.before==null){Hook(hook,"beforeMove",index);MoveAbsent(candidate,target);}else{LauncherMaintenance.NoReparse(target);File.Replace(candidate,target,old);byte[] displaced=Read(old,slot.target=="config"?2097152:1048576);if(!Same(slot.before,displaced)){WriteNew(Path.Combine(folder,"foreign"),displaced);Hook(hook,"beforeCompensate",index);RetireOwned(target,Path.Combine(folder,"retired"),slot.after,()=>{Hook(hook,"beforeMove",index);MoveAbsent(old,target);});throw new IOException("原子写入时目标改变，已保留并发修改证据。");}}if(!Same(slot.after,Read(target,slot.target=="config"?2097152:1048576)))throw new IOException("写入结果已被外部修改。");}
  static bool Rollback(Engine e,Record r,Func<bool> running,Action<string,int> hook){Save(e,r,"rollingBack");bool okay=true;for(int i=r.entries.Count-1;i>=0;i--){var entry=r.entries[i];if(!entry.attempted)continue;try{Safe(e,running);string target=Target(e,r,entry.target);StageEvidence(target,r,i,entry);byte[] current=Read(target,entry.target=="config"?2097152:1048576);if(Hash(current)==entry.before)continue;if(Hash(current)!=entry.after){okay=false;continue;}string folder=Stage(target,r,i);Private(folder);string candidate=Path.Combine(folder,"restore");byte[] before=Read(Backup(e,r,i,false),entry.target=="config"?2097152:1048576);if(before!=null){if(File.Exists(candidate)){if(!Same(before,Read(candidate)))throw new IOException("恢复暂存数据改变。");}else WriteNew(candidate,before);}Hook(hook,"beforeRollback",i);bool owned=RetireOwned(target,Path.Combine(folder,"retired"),current,()=>{if(before!=null){Hook(hook,"beforeMove",i);MoveAbsent(candidate,target);}});if(!owned||Hash(Read(target,entry.target=="config"?2097152:1048576))!=entry.before)okay=false;}catch(Exception ex){if(ex is OutOfMemoryException||ex is StackOverflowException)throw;okay=false;}}if(okay)Finish(e,r,"failed");else Save(e,r,"recoveryRequired");return okay;}
  static PlayProfileResult Result(Engine e,string status,string message,string id,Func<bool> running){var recovery=Recovery(e,running);return new PlayProfileResult{status=status,message=message,profileId=id,recoveryPending=recovery.pending,pendingRecovery=recovery};}
  internal static object Apply(Engine e,PlayProfilePlan plan,Func<bool> running,Func<LauncherMemoryInfo> memory,Action<string,int> hook,Func<bool> cancelled){Safe(e,running);if(cancelled())throw new OperationCanceledException();if(Pending(e))throw new IOException(PendingMessage);e.GuardContent();if(plan.Slots.Count==0)return Result(e,"unchanged","当前配置已匹配；未写入游戏文件。",plan.Id,running);if(plan.Slots.Count>5||plan.Slots.Any(slot=>slot.after==null||slot.after.Length>(slot.target=="config"?2097152:1048576))||plan.Slots.Sum(s=>(long)(s.before==null?0:s.before.Length)+s.after.Length)>12582912)throw new IOException("事务超过文件或累计大小限制。");Record r=null;try{Private(Root(e));r=new Record{id=Guid.NewGuid().ToString("N"),binding=Binding(e),profileId=plan.Id,targetKind=plan.Kind,targetId=plan.Target};Private(Transaction(e,r));for(int i=0;i<plan.Slots.Count;i++){var slot=plan.Slots[i];Target(e,r,slot.target);if(slot.before!=null)WriteNew(Backup(e,r,i,false),slot.before);WriteNew(Backup(e,r,i,true),slot.after);r.entries.Add(new Entry{target=slot.target,before=Hash(slot.before),after=Hash(slot.after)});}Save(e,r,"prepared");for(int i=0;i<plan.Slots.Count;i++){Safe(e,running);if(cancelled())throw new OperationCanceledException();e.GuardContent(true);if(plan.Heap.HasValue)LauncherMaintenance.CheckProfileHeap(plan.Heap.Value,memory);r.entries[i].attempted=true;Save(e,r,"applying");Hook(hook,"beforeWrite",i);Safe(e,running);Forward(e,r,i,plan.Slots[i],hook,memory,plan.Heap,cancelled,running);Hook(hook,"afterWrite",i);}Safe(e,running);if(plan.Heap.HasValue)LauncherMaintenance.CheckProfileHeap(plan.Heap.Value,memory);Finish(e,r,"completed");return Result(e,"completed","游玩配置已应用，下次启动读取。",plan.Id,running);}catch(Exception ex){if(ex is OutOfMemoryException||ex is StackOverflowException)throw;bool rolledBack=false;if(r!=null&&r.Raw!=null){try{rolledBack=Rollback(e,r,running,hook);}catch{}}bool pending=Pending(e);return Result(e,pending?"recoveryRequired":ex is OperationCanceledException?"cancelled":"failed",pending?"应用未完成；部分配置需要明确恢复，外部修改与事务证据已保留。":rolledBack?"应用失败；本轮自有改动已安全回滚。":"应用失败；未完成游戏配置写入。",plan.Id,running);}}
  internal static object Recover(Engine e,string stamp,Func<bool> running,Action<string,int> hook){Safe(e,running);var state=Recovery(e,running);if(!state.pending||!state.canRecover||string.IsNullOrEmpty(stamp)||state.stamp!=stamp)throw new IOException("恢复预览已过期或存在外部修改，请重新核对。");var r=Load(e);if(Recovery(e,running).stamp!=stamp)throw new IOException("恢复证据已改变。");bool okay;try{okay=Rollback(e,r,running,hook);}catch{okay=false;}return Result(e,okay?"recovered":"recoveryRequired",okay?"已恢复本轮自有配置；保留完整事务证据。":"恢复未完成；外部修改和私有事务证据已保留。",r.profileId,running);}
 }
